        else:
            core = version_part
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are either None or lists of strings
        # Version without pre-release sorts after version with pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:  # pre1 has no pre-release
            return 1  # sorts after
        if pre2 is None:  # pre2 has no pre-release
            return -1  # pre1 sorts before

        # Both have pre-releases, compare identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # id1 is numeric, id2 is not, numeric sorts first
                return -1
            elif is_digit2:
                # id2 is numeric, id1 is not, numeric sorts first
                return 1
            else:
                # Both are non-numeric, compare lexicographically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def compare_versions(v1, v2):
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        # Compare core version
        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        # Compare pre-release
        return compare_prerelease(pre1, pre2)

    from functools import cmp_to_key
    return sorted(versions, key=cmp_to_key(compare_versions))

